/**
 * Agoraya — Foundation database schema (Drizzle ORM).
 *
 * This file defines the shared, cross-module foundation tables:
 * tenants, users, sessions, RBAC, tickets/reports, audit events and BPS
 * snapshots. Individual feature modules extend this schema with their own
 * domain tables under `src/modules/<feature>/` and combine them here as the
 * modular monolith grows.
 *
 * Conventions (docs/ai/DOCUMENTATION.md §16.2):
 * - Tables: snake_case
 * - Columns: snake_case
 * - Primary keys: UUID (generated by the caller / server default)
 * - Audit columns: `created_at` / `updated_at`
 * - Sensitive/demo data is explicitly synthetic; real NIK/PII is never stored here.
 */

import {
  pgTable,
  uuid,
  varchar,
  text,
  timestamp,
  integer,
  jsonb,
  primaryKey,
  index,
  uniqueIndex,
  pgEnum,
} from "drizzle-orm/pg-core";

// ---------------------------------------------------------------------------
// Enums
// ---------------------------------------------------------------------------

export const userStatusEnum = pgEnum("user_status", [
  "active",
  "inactive",
  "suspended",
]);

export const ticketStatusEnum = pgEnum("ticket_status", [
  "draft",
  "submitted",
  "in_progress",
  "resolved",
  "rejected",
  "closed",
]);

export const bpsSourceEnum = pgEnum("bps_source", [
  "BPS_API",
  "SIMULATED",
  "CITIZEN_UNVERIFIED",
]);

// ---------------------------------------------------------------------------
// Helper: shared audit columns
// ---------------------------------------------------------------------------

const auditColumns = {
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
};

// ---------------------------------------------------------------------------
// Tenants
// ---------------------------------------------------------------------------

export const tenants = pgTable("tenants", {
  id: uuid("id").primaryKey().notNull(),
  name: varchar("name", { length: 255 }).notNull(),
  slug: varchar("slug", { length: 100 }).notNull().unique(),
  status: varchar("status", { length: 50 }).notNull().default("active"),
  ...auditColumns,
});

// ---------------------------------------------------------------------------
// Users (mock / simulated identity only — no real Dukcapil/SIASN data)
// ---------------------------------------------------------------------------

export const users = pgTable(
  "users",
  {
    id: uuid("id").primaryKey().notNull(),
    tenantId: uuid("tenant_id")
      .references(() => tenants.id, { onDelete: "cascade" })
      .notNull(),
    email: varchar("email", { length: 255 }).notNull().unique(),
    name: varchar("name", { length: 255 }).notNull(),
    nik: varchar("nik", { length: 32 }), // SIMULATED only — never a real NIK
    status: userStatusEnum("user_status").notNull().default("active"),
    ...auditColumns,
  },
  (t) => ({
    tenantIdx: index("users_tenant_id_idx").on(t.tenantId),
    emailIdx: uniqueIndex("users_email_lower_idx").on(t.email),
  }),
);

// ---------------------------------------------------------------------------
// Sessions
// ---------------------------------------------------------------------------

export const userSessions = pgTable(
  "user_sessions",
  {
    id: uuid("id").primaryKey().notNull(),
    userId: uuid("user_id")
      .references(() => users.id, { onDelete: "cascade" })
      .notNull(),
    tokenHash: varchar("token_hash", { length: 255 }).notNull().unique(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    ...auditColumns,
  },
  (t) => ({
    userIdx: index("user_sessions_user_id_idx").on(t.userId),
  }),
);

// ---------------------------------------------------------------------------
// OTP codes (hashed, short-lived, attempt-limited)
// ---------------------------------------------------------------------------

export const otpCodes = pgTable(
  "otp_codes",
  {
    id: uuid("id").primaryKey().notNull(),
    identifierHash: varchar("identifier_hash", { length: 255 }).notNull(),
    codeHash: varchar("code_hash", { length: 255 }).notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    attempts: integer("attempts").notNull().default(0),
    ...auditColumns,
  },
  (t) => ({
    identifierIdx: index("otp_codes_identifier_hash_idx").on(t.identifierHash),
  }),
);

// ---------------------------------------------------------------------------
// RBAC
// ---------------------------------------------------------------------------

export const roles = pgTable(
  "roles",
  {
    id: uuid("id").primaryKey().notNull(),
    tenantId: uuid("tenant_id")
      .references(() => tenants.id, { onDelete: "cascade" })
      .notNull(),
    name: varchar("name", { length: 100 }).notNull(),
    key: varchar("key", { length: 100 }).notNull(),
    ...auditColumns,
  },
  (t) => ({
    tenantKeyIdx: uniqueIndex("roles_tenant_id_key_idx").on(t.tenantId, t.key),
  }),
);

export const permissions = pgTable("permissions", {
  id: uuid("id").primaryKey().notNull(),
  key: varchar("key", { length: 100 }).notNull().unique(),
  description: text("description"),
  ...auditColumns,
});

export const rolePermissions = pgTable(
  "role_permissions",
  {
    roleId: uuid("role_id")
      .references(() => roles.id, { onDelete: "cascade" })
      .notNull(),
    permissionId: uuid("permission_id")
      .references(() => permissions.id, { onDelete: "cascade" })
      .notNull(),
    grantedAt: timestamp("granted_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    grantedBy: uuid("granted_by").references(() => users.id, { onDelete: "set null" }),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
  },
  (t) => ({
    pk: primaryKey({ columns: [t.roleId, t.permissionId] }),
  }),
);

export const userRoles = pgTable(
  "user_roles",
  {
    userId: uuid("user_id")
      .references(() => users.id, { onDelete: "cascade" })
      .notNull(),
    roleId: uuid("role_id")
      .references(() => roles.id, { onDelete: "cascade" })
      .notNull(),
    grantedAt: timestamp("granted_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    grantedBy: uuid("granted_by").references(() => users.id, { onDelete: "set null" }),
    expiresAt: timestamp("expires_at", { withTimezone: true }),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
  },
  (t) => ({
    pk: primaryKey({ columns: [t.userId, t.roleId] }),
    roleIdx: index("user_roles_role_id_idx").on(t.roleId),
  }),
);

// ---------------------------------------------------------------------------
// RBAC: policies (PDP policy definitions)
// ---------------------------------------------------------------------------

export const rbacPolicies = pgTable(
  "rbac_policies",
  {
    id: uuid("id").primaryKey().notNull(),
    key: varchar("key", { length: 100 }).notNull().unique(),
    name: varchar("name", { length: 200 }).notNull(),
    description: text("description"),
    effect: varchar("effect", { length: 20 }).notNull().default("allow"),
    priority: integer("priority").notNull().default(100),
    status: varchar("status", { length: 20 }).notNull().default("active"),
    version: integer("version").notNull().default(1),
    tenantId: uuid("tenant_id").references(() => tenants.id, { onDelete: "cascade" }),
    roles: jsonb("roles").$type<string[]>().notNull(),
    permissions: jsonb("permissions").$type<string[]>().notNull(),
    resources: jsonb("resources").$type<string[]>().notNull(),
    actions: jsonb("actions").$type<string[]>().notNull(),
    conditions: jsonb("conditions").$type<unknown>().notNull(),
    ...auditColumns,
  },
  (t) => ({
    statusIdx: index("rbac_policies_status_idx").on(t.status),
    tenantIdx: index("rbac_policies_tenant_id_idx").on(t.tenantId),
  }),
);

// ---------------------------------------------------------------------------
// RBAC: policy version history (append-only review trail)
// ---------------------------------------------------------------------------

export const rbacPolicyVersions = pgTable(
  "rbac_policy_versions",
  {
    id: uuid("id").primaryKey().notNull(),
    policyId: uuid("policy_id")
      .references(() => rbacPolicies.id, { onDelete: "cascade" })
      .notNull(),
    policyKey: varchar("policy_key", { length: 100 }).notNull(),
    version: integer("version").notNull(),
    definition: jsonb("definition").$type<unknown>().notNull(),
    changedBy: uuid("changed_by").references(() => users.id, { onDelete: "set null" }),
    reason: text("reason"),
    ...auditColumns,
  },
  (t) => ({
    policyVersionIdx: uniqueIndex("rbac_policy_versions_policy_id_version_idx").on(
      t.policyId,
      t.version,
    ),
    policyKeyIdx: index("rbac_policy_versions_policy_key_idx").on(t.policyKey),
  }),
);

// ---------------------------------------------------------------------------
// Civic reporting / tickets
// ---------------------------------------------------------------------------

export const tickets = pgTable(
  "tickets",
  {
    id: uuid("id").primaryKey().notNull(),
    tenantId: uuid("tenant_id")
      .references(() => tenants.id, { onDelete: "cascade" })
      .notNull(),
    citizenId: uuid("citizen_id").references(() => users.id),
    category: varchar("category", { length: 100 }).notNull(),
    title: varchar("title", { length: 255 }).notNull(),
    description: text("description").notNull(),
    status: ticketStatusEnum("ticket_status").notNull().default("draft"),
    urgency: varchar("urgency", { length: 50 }).notNull().default("medium"),
    location: jsonb("location"),
    ...auditColumns,
  },
  (t) => ({
    tenantIdx: index("tickets_tenant_id_idx").on(t.tenantId),
    statusIdx: index("tickets_status_idx").on(t.status),
    citizenIdx: index("tickets_citizen_id_idx").on(t.citizenId),
  }),
);

export const ticketAuditLogs = pgTable(
  "ticket_audit_logs",
  {
    id: uuid("id").primaryKey().notNull(),
    ticketId: uuid("ticket_id")
      .references(() => tickets.id, { onDelete: "cascade" })
      .notNull(),
    actorId: uuid("actor_id").references(() => users.id),
    action: varchar("action", { length: 100 }).notNull(),
    previousState: varchar("previous_state", { length: 50 }),
    newState: varchar("new_state", { length: 50 }),
    reason: text("reason"),
    ...auditColumns,
  },
  (t) => ({
    ticketIdx: index("ticket_audit_logs_ticket_id_idx").on(t.ticketId),
  }),
);

// ---------------------------------------------------------------------------
// BPS snapshots (synthetic / simulated public statistics)
// ---------------------------------------------------------------------------

export const bpsSnapshots = pgTable(
  "bps_snapshots",
  {
    id: uuid("id").primaryKey().notNull(),
    dataset: varchar("dataset", { length: 100 }).notNull(),
    region: varchar("region", { length: 100 }).notNull(),
    year: integer("year").notNull(),
    month: integer("month").notNull(),
    payload: jsonb("payload").notNull(),
    sourceLabel: bpsSourceEnum("source_label").notNull().default("SIMULATED"),
    fetchedAt: timestamp("fetched_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    ...auditColumns,
  },
  (t) => ({
    unq: uniqueIndex("bps_snapshots_dataset_region_year_month_idx").on(
      t.dataset,
      t.region,
      t.year,
      t.month,
    ),
  }),
);

// ---------------------------------------------------------------------------
// Global append-only audit events
// ---------------------------------------------------------------------------

export const auditEvents = pgTable(
  "audit_events",
  {
    id: uuid("id").primaryKey().notNull(),
    actorId: uuid("actor_id").references(() => users.id),
    action: varchar("action", { length: 100 }).notNull(),
    targetTable: varchar("target_table", { length: 100 }).notNull(),
    targetId: uuid("target_id"),
    metadata: jsonb("metadata"),
    ...auditColumns,
  },
  (t) => ({
    actorIdx: index("audit_events_actor_id_idx").on(t.actorId),
    createdIdx: index("audit_events_created_at_idx").on(t.createdAt),
  }),
);

// ---------------------------------------------------------------------------
// All tables (used by the Drizzle client and seed scripts)
// ---------------------------------------------------------------------------

export const tables = {
  tenants,
  users,
  userSessions,
  otpCodes,
  roles,
  permissions,
  rolePermissions,
  userRoles,
  rbacPolicies,
  rbacPolicyVersions,
  tickets,
  ticketAuditLogs,
  bpsSnapshots,
  auditEvents,
} as const;
